const FORBIDDEN = ['seafood', 'fish', 'shellfish', 'shell', 'live', 'smoked', 'stick', 'sticks', 'white', 'fillet', 'fillets', 'cod', 'oyster', 'oysters', 'clam', 'clams', 'mussel', 'mussels', 'salmon', 'shrimp', 'tuna', 'king', 'sea', 'tail', 'tails', 'legs'];
