  const al = nonEmpty(byId('seafood_counter')?.aliases ?? [], 'seafood_counter aliases', 4);
  const FOLD_SHORT = ['fresh_vs_previously_frozen_fish', 'fish_freshness_at_counter'].flatMap((id) => PRE.entries.find((e) => e.id === id)?.aliases ?? [])
