export const beforeTwoLine = (e) => {
  if (!e || !TWO_LINE[e.id]) return e;
  const p = PRE.entries.find((x) => x.id === e.id);
  return { ...e, ...Object.fromEntries(Object.keys(TWO_LINE[e.id]).map((k) => [k, p[k]])) };
};

